import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { machineApi } from '../services/api';
import DashboardCard from '../components/DashboardCard';
import StatusChart from '../components/StatusChart';
import ActivityFeed from '../components/ActivityFeed';
import { Server, PlayCircle, PauseCircle, Wrench, AlertTriangle, ArrowRight, Plus } from 'lucide-react';

const DashboardPage = () => {
  const navigate = useNavigate();
  const [stats, setStats] = useState({
    totalAssets: 0,
    runningCount: 0,
    idleCount: 0,
    maintenanceCount: 0,
    highCriticalityCount: 0,
    recentActivities: [],
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      setLoading(true);
      const res = await machineApi.getStats();
      if (res.data.success) {
        setStats(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch dashboard metrics:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <div className="page-header">
        <div className="page-title-group">
          <h1>Asset Operations Dashboard</h1>
          <p>Real-Time Digital Twin Monitoring & Loom Asset Capacity Overview</p>
        </div>
        <div style={{ display: 'flex', gap: '0.75rem' }}>
          <button className="btn btn-secondary" onClick={() => navigate('/assets')}>
            View All Assets <ArrowRight size={16} />
          </button>
          <button className="btn btn-primary" onClick={() => navigate('/assets/new')}>
            <Plus size={16} /> Add Asset
          </button>
        </div>
      </div>

      {/* 5 Metric Summary Cards */}
      <div className="dashboard-grid">
        <DashboardCard
          title="Total Machine Assets"
          value={loading ? '...' : stats.totalAssets}
          subtitle="Registered Loom Inventory"
          icon={Server}
          colorClass="icon-blue"
        />
        <DashboardCard
          title="Running Assets"
          value={loading ? '...' : stats.runningCount}
          subtitle="Active Sensor Streams"
          icon={PlayCircle}
          colorClass="icon-green"
        />
        <DashboardCard
          title="Idle Assets"
          value={loading ? '...' : stats.idleCount}
          subtitle="Standby / Off-Shift"
          icon={PauseCircle}
          colorClass="icon-yellow"
        />
        <DashboardCard
          title="Under Maintenance"
          value={loading ? '...' : stats.maintenanceCount}
          subtitle="Service & Repairs"
          icon={Wrench}
          colorClass="icon-red"
        />
        <DashboardCard
          title="High Criticality"
          value={loading ? '...' : stats.highCriticalityCount}
          subtitle="Mission-Critical Assets"
          icon={AlertTriangle}
          colorClass="icon-purple"
        />
      </div>

      {/* Main Layout Grid: Chart + Activity Feed */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(350px, 1fr))', gap: '1.5rem' }}>
        {/* Status Distribution Chart Card */}
        <div className="glass-card" style={{ padding: '1.75rem' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
            <h3 style={{ fontSize: '1.1rem', fontWeight: '700' }}>Fleet Status Breakdown</h3>
            <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>Real-Time Sensor Sync</span>
          </div>
          <StatusChart
            running={stats.runningCount}
            idle={stats.idleCount}
            maintenance={stats.maintenanceCount}
          />
        </div>

        {/* Recent Activity Feed Card */}
        <div className="glass-card" style={{ padding: '1.75rem' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
            <h3 style={{ fontSize: '1.1rem', fontWeight: '700' }}>Recent Activity Feed</h3>
            <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>Last 5 Asset Actions</span>
          </div>
          <ActivityFeed activities={stats.recentActivities} />
        </div>
      </div>
    </div>
  );
};

export default DashboardPage;
